    """Copy Student.primary_guardian into StudentGuardian and give existing
    guardians a code (GRD-<year>-NNNNN, continuing the per-org sequence)."""
    from django.utils import timezone

    Student = apps.get_model("students", "Student")
    Guardian = apps.get_model("guardians", "Guardian")
    StudentGuardian = apps.get_model("guardians", "StudentGuardian")
    DocumentSequence = apps.get_model("core", "DocumentSequence")

    links = [
        StudentGuardian(
            organization_id=s.organization_id, school_id=s.school_id, student_id=s.id,
            guardian_id=s.primary_guardian_id, relation=s.primary_guardian.relation,
            is_primary=True,
        )
        for s in Student.objects.filter(primary_guardian__isnull=False).select_related("primary_guardian")
    ]
    StudentGuardian.objects.bulk_create(links)

    year = timezone.localdate().year
    counters = {}
    for g in Guardian.objects.filter(guardian_code="").order_by("organization_id", "created_at"):
        counters[g.organization_id] = counters.get(g.organization_id, 0) + 1
        g.guardian_code = f"GRD-{year}-{counters[g.organization_id]:05d}"
        g.save(update_fields=["guardian_code"])
    for org_id, last in counters.items():
        DocumentSequence.objects.update_or_create(
            organization_id=org_id, key=f"grd:{year}", defaults={"last_value": last}
        )


